set -euo pipefail
git fetch origin work/photomap-straighten-20260912
test "$(git rev-parse HEAD)" = "96d849bdbdafd656783d0be78f4510852ca0d0b7"
test "$(git rev-parse origin/work/photomap-straighten-20260912)" = "96d849bdbdafd656783d0be78f4510852ca0d0b7"
test -z "$(git status --porcelain)"
cd frontend
npm run build >/dev/null
python3 - <<'PY'
from pathlib import Path
import gzip, json
p=next(Path('dist/assets').glob('public-map-*.js'))
data=p.read_bytes()
Path('/tmp/photomap-public-map-before-086.json').write_text(json.dumps({'raw':len(data),'gzip':len(gzip.compress(data,mtime=0))}))
print('baseline_public_map='+Path('/tmp/photomap-public-map-before-086.json').read_text())
PY
cd ..
trap 'status=$?; if [ $status -ne 0 ]; then echo experiment_failed_restoring_files; git diff -- frontend/src/components/map/PlaceMap.tsx frontend/src/components/admin/AdminPlacesModalLayer.tsx || true; git restore --source=origin/work/photomap-straighten-20260912 --staged --worktree frontend/src/components/map/PlaceMap.tsx frontend/src/components/admin/AdminPlacesModalLayer.tsx || true; fi; exit $status' EXIT
python3 - <<'PY'
from pathlib import Path

p=Path('frontend/src/components/map/PlaceMap.tsx')
s=p.read_text()
s=s.replace('import { useCallback, useEffect, useMemo, useRef, useState } from "react";', 'import { lazy, Suspense, useCallback, useEffect, useMemo, useRef, useState } from "react";', 1)
s=s.replace('import { PhotoDetailModal } from "./PhotoDetailModal";\n', '', 1)
anchor='const EMPTY_PLACE_GALLERY_ITEMS: PlaceMapVisualItem[] = [];\n'
if anchor not in s:
    raise SystemExit('PlaceMap lazy anchor missing')
s=s.replace(anchor, 'const LazyPhotoDetailModal = lazy(() => import("./PhotoDetailModal").then((module) => ({ default: module.PhotoDetailModal })));\n\n'+anchor, 1)
old='''      {detailItem && detailPlace ? (
        <PhotoDetailModal
          customFieldDefinitions={placeCustomFieldDefinitions}
          isAudioAutoplayEnabled={isAudioAutoplayEnabled}
          item={detailItem}
          navigationItems={detailNavigationItems}
          place={detailPlace}
          onPin={(pinRequest) => {
            const didPin = onPinMedia({ item: detailItem, place: detailPlace, ...pinRequest });
            if (didPin) {
              setVisualDetail(null);
            }

            return didPin;
          }}
          onNavigate={(nextItem) => {
            setVisualDetail({ id: nextItem.id, kind: nextItem.kind, placeId: detailPlace.id });
          }}
          onReport={() => setReportTarget({ id: detailItem.id, kind: detailItem.kind, placeId: detailPlace.id })}
          onClose={() => {
            setVisualDetail(null);
          }}
        />
      ) : null}
'''
new='''      {detailItem && detailPlace ? (
        <Suspense fallback={null}>
          <LazyPhotoDetailModal
            customFieldDefinitions={placeCustomFieldDefinitions}
            isAudioAutoplayEnabled={isAudioAutoplayEnabled}
            item={detailItem}
            navigationItems={detailNavigationItems}
            place={detailPlace}
            onPin={(pinRequest) => {
              const didPin = onPinMedia({ item: detailItem, place: detailPlace, ...pinRequest });
              if (didPin) {
                setVisualDetail(null);
              }

              return didPin;
            }}
            onNavigate={(nextItem) => {
              setVisualDetail({ id: nextItem.id, kind: nextItem.kind, placeId: detailPlace.id });
            }}
            onReport={() => setReportTarget({ id: detailItem.id, kind: detailItem.kind, placeId: detailPlace.id })}
            onClose={() => {
              setVisualDetail(null);
            }}
          />
        </Suspense>
      ) : null}
'''
if old not in s:
    raise SystemExit('PlaceMap PhotoDetail block mismatch')
s=s.replace(old,new,1)
p.write_text(s)

p=Path('frontend/src/components/admin/AdminPlacesModalLayer.tsx')
s=p.read_text()
s=s.replace('import { useEffect, useState } from "react";', 'import { lazy, Suspense, useEffect, useState } from "react";', 1)
s=s.replace('import { AdminPlacePublicPreviewModal } from "./AdminPlacePublicPreviewModal";\n', '', 1)
anchor='type Props = {\n'
if anchor not in s:
    raise SystemExit('AdminPlacesModalLayer lazy anchor missing')
s=s.replace(anchor, 'const LazyAdminPlacePublicPreviewModal = lazy(() =>\n  import("./AdminPlacePublicPreviewModal").then((module) => ({ default: module.AdminPlacePublicPreviewModal })),\n);\n\n'+anchor, 1)
old='''      {appConfig && publicPreviewPlace ? (
        <AdminPlacePublicPreviewModal
          customFieldDefinitions={appConfig.place_custom_fields}
          place={publicPreviewPlace}
          onClose={() => onPublicPreviewPlaceIdChange(null)}
        />
      ) : null}
'''
new='''      {appConfig && publicPreviewPlace ? (
        <Suspense fallback={null}>
          <LazyAdminPlacePublicPreviewModal
            customFieldDefinitions={appConfig.place_custom_fields}
            place={publicPreviewPlace}
            onClose={() => onPublicPreviewPlaceIdChange(null)}
          />
        </Suspense>
      ) : null}
'''
if old not in s:
    raise SystemExit('Admin public preview block mismatch')
s=s.replace(old,new,1)
p.write_text(s)
PY
cd frontend
npm run test -- src/components/admin/AdminPlacePublicPreviewModal.test.tsx src/components/map/PhotoDetailModal.test.tsx
npm run lint
npm run build
python3 - <<'PY'
from pathlib import Path
import gzip, json
before=json.loads(Path('/tmp/photomap-public-map-before-086.json').read_text())
p=next(Path('dist/assets').glob('public-map-*.js'))
data=p.read_bytes()
after={'raw':len(data),'gzip':len(gzip.compress(data,mtime=0))}
print('public_map_before='+json.dumps(before,sort_keys=True))
print('public_map_after='+json.dumps(after,sort_keys=True))
print('public_map_delta_raw='+str(after['raw']-before['raw']))
print('public_map_delta_gzip='+str(after['gzip']-before['gzip']))
async_chunks=sorted(x.name for x in Path('dist/assets').glob('PhotoDetailModal-*.js'))
print('photo_detail_async_chunks='+json.dumps(async_chunks))
if before['gzip']-after['gzip'] < 4000:
    raise SystemExit('gzip reduction below 4KB threshold')
if not async_chunks:
    raise SystemExit('PhotoDetailModal was not emitted as an async chunk')
PY
cd ..
VENV=$(mktemp -d /tmp/photomap-photo-detail-chain-e2e-XXXXXX)
trap 'status=$?; ./scripts/devctl.sh stop >/dev/null 2>&1 || true; rm -rf "$VENV"; if [ $status -ne 0 ]; then echo experiment_failed_restoring_files; git diff -- frontend/src/components/map/PlaceMap.tsx frontend/src/components/admin/AdminPlacesModalLayer.tsx || true; git restore --source=origin/work/photomap-straighten-20260912 --staged --worktree frontend/src/components/map/PlaceMap.tsx frontend/src/components/admin/AdminPlacesModalLayer.tsx || true; fi; exit $status' EXIT
python3 -m venv "$VENV"
"$VENV/bin/python" -m pip install -q -r backend/requirements.txt
cd frontend
PYTHON="$VENV/bin/python" npm run test:e2e -- e2e/visual/map.spec.ts e2e/visual/map-gallery-sizing.spec.ts e2e/visual/map-trackpad-zoom.spec.ts e2e/visual/admin.spec.ts --project=chromium --grep-invert 'visual:'
cd ..
git diff --check
git add frontend/src/components/map/PlaceMap.tsx frontend/src/components/admin/AdminPlacesModalLayer.tsx
git commit -m 'Lazy load photo detail flows'
git push origin HEAD:work/photomap-straighten-20260912
printf 'published_sha=' && git rev-parse HEAD
trap - EXIT

